  "description": "בני משפחה של נכי צה\"ל זכאים להחזר על טיפול נפשי: פרטני, זוגי, משפחתי או קבוצתי. התנאי: לנכה נקבעו 20% נכות ומעלה (או 10% אם הוכר לפני 1996) בגלל פוסט טראומה, פגיעה נפשית או פגיעת ראש, או 100% נכות ומעלה מכל סיבה. זכאים הורים, בן/בת זוג וילדים בגילי 7 עד 30. ההחזר עד 384 ₪ (כולל מע\"מ) לשעת טיפול בשבוע, לכל אחד. משפחות של פצועי חרבות ברזל שקיבלו הכרה עקרונית זכאיות ל-12 מפגשים (ועוד 12 לפי הצורך) במכון בהסדר או בהחזר.",
